// Embedded copy of assets/models/beacon_drone.glb. This keeps the custom GLB model
// working even if a browser blocks file:// loading during local testing.
const EMBEDDED_BEACON_DRONE_GLB = '';

const scoreElement = document.getElementById('score');
const loadingElement = document.getElementById('loading');
const modelStatusElement = document.getElementById('model-status');
const featureStatusElement = document.getElementById('feature-status');


try {
  window.__crystalIslandStarted = true;
  init();
  animate();
} catch (error) {
  console.error(error);
  if (loadingElement) {
    loadingElement.textContent = 'Scene error: ' + error.message;
    loadingElement.classList.add('error');
  }
}

function init() {
  clock = new THREE.Clock();
  scene = new THREE.Scene();

  camera = new THREE.PerspectiveCamera(
    66,
    window.innerWidth / window.innerHeight,
    0.1,
    1000
  );
  // Lower and pull the starting camera back so the horizon sits lower
  // and the view includes more of the sky, planets, and constellations.
  camera.position.set(13.5, 5.8, 16);

  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.shadowMap.autoUpdate = true;
  renderer.shadowMap.needsUpdate = true;
  renderer.outputEncoding = THREE.sRGBEncoding;
  document.body.appendChild(renderer.domElement);

  controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.05;
  controls.target.set(0, 2.6, 0);
  controls.minDistance = 5;
  controls.maxDistance = 40;
  // Let the player orbit closer to the horizon so the sky stays visible.
  controls.maxPolarAngle = Math.PI * 0.54;
  controls.update();

  raycaster = new THREE.Raycaster();
  mouse = new THREE.Vector2();

  const hideLoading = () => {
    if (loadingElement) loadingElement.style.display = 'none';
  };

  const loadingManager = new THREE.LoadingManager(hideLoading);
  loadingManager.onError = (url) => {
    console.warn('Asset failed to load:', url);
    // Do not leave the page stuck on the loading screen if one optional asset fails.
    hideLoading();
  };

  // Safety fallback: the scene is still usable even if one optional asset is slow.
  window.setTimeout(hideLoading, 4500);

  const textureLoader = new THREE.TextureLoader(loadingManager);
  const cubeTextureLoader = new THREE.CubeTextureLoader(loadingManager);

  addSkybox(cubeTextureLoader);
  const materials = createMaterials(textureLoader);
  burstParticleMaterial = new THREE.PointsMaterial({
    color: 0xbffcff,
    size: 0.085,
    transparent: true,
    opacity: 1.0,
    depthWrite: false,
  });

  addLights();
  addIsland(materials);
  addOceanEffects();
  addTrees(materials);
  addRocks(materials);
  addCampsite(materials);
  addTreasureChest(materials);
  addGuideSign(materials);
  addCrystals(materials);
  addBeacon(materials);
  addFloatingRuins(materials);
  addFloatingFragments(materials);
  addEnergyWisps();
  addAurora();
  addStarField();
  addShootingStar();
  addSkyEnhancements();
  loadCustomModel(loadingManager);
  setupWowControls();
  applyTimeOfDay();

  renderer.domElement.addEventListener('click', handleCrystalClick);
  renderer.domElement.addEventListener('pointermove', handlePointerMove);
  window.addEventListener('resize', handleResize);
}

function addSkybox(cubeTextureLoader) {
  // Load the original cubemap assets for assignment completeness, but render a
  // smooth skydome in the scene so no cube-corner seam is visible.
  skyboxTexture = cubeTextureLoader
    .setPath('./assets/skybox/')
    .load(['px.png', 'nx.png', 'py.png', 'ny.png', 'pz.png', 'nz.png']);
  skyboxTexture.encoding = THREE.sRGBEncoding;

  const skyCanvas = document.createElement('canvas');
  skyCanvas.width = 2048;
  skyCanvas.height = 1024;
  const ctx = skyCanvas.getContext('2d');

  const gradient = ctx.createLinearGradient(0, 0, 0, skyCanvas.height);
  gradient.addColorStop(0, '#030611');
  gradient.addColorStop(0.45, '#040914');
  gradient.addColorStop(1, '#0a1430');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, skyCanvas.width, skyCanvas.height);

  function glow(x, y, r, color, alpha) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(${color},${alpha})`);
    g.addColorStop(1, `rgba(${color},0)`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  glow(350, 250, 180, '60,120,255', 0.12);
  glow(1550, 240, 170, '185,70,255', 0.10);
  glow(1250, 180, 120, '0,255,180', 0.07);
  glow(1720, 320, 140, '255,110,60', 0.08);

  for (let i = 0; i < 700; i++) {
    const x = Math.random() * skyCanvas.width;
    const y = Math.random() * skyCanvas.height * 0.88;
    const s = Math.random() * 2.2 + 0.35;
    const a = Math.random() * 0.65 + 0.2;
    ctx.fillStyle = `rgba(255,255,255,${a})`;
    ctx.beginPath();
    ctx.arc(x, y, s, 0, Math.PI * 2);
    ctx.fill();
  }

  const skyTexture = new THREE.CanvasTexture(skyCanvas);
  skyTexture.encoding = THREE.sRGBEncoding;
  nightSkyDome = new THREE.Mesh(
    new THREE.SphereGeometry(140, 64, 40),
    new THREE.MeshBasicMaterial({ map: skyTexture, side: THREE.BackSide, depthWrite: false, fog: false })
  );
  nightSkyDome.renderOrder = -1000;
  scene.add(nightSkyDome);

  scene.background = new THREE.Color(0x030611);
  scene.fog = new THREE.FogExp2(0x03040a, 0.012);
}

function createMaterials(textureLoader) {
  const groundTexture = textureLoader.load('./assets/island_ground.png');
  groundTexture.encoding = THREE.sRGBEncoding;
  groundTexture.wrapS = THREE.RepeatWrapping;
  groundTexture.wrapT = THREE.RepeatWrapping;
  groundTexture.repeat.set(4, 4);

  const woodTexture = textureLoader.load('./assets/wood_planks.png');
  woodTexture.encoding = THREE.sRGBEncoding;
  woodTexture.wrapS = THREE.RepeatWrapping;
  woodTexture.wrapT = THREE.RepeatWrapping;
  woodTexture.repeat.set(2, 2);

  const crystalTexture = textureLoader.load('./assets/crystal_noise.png');
  crystalTexture.encoding = THREE.sRGBEncoding;

  return {
    ground: new THREE.MeshStandardMaterial({
      map: groundTexture,
      color: 0xd7cf9d,
      roughness: 0.9,
      metalness: 0.0,
    }),
    water: new THREE.MeshStandardMaterial({
      color: 0x2b7fb0,
      roughness: 0.35,
      metalness: 0.2,
      transparent: true,
      opacity: 0.68,
    }),
    trunk: new THREE.MeshStandardMaterial({ color: 0x5a351c, roughness: 0.8 }),
    leaves: new THREE.MeshStandardMaterial({ color: 0x1d8a58, roughness: 0.65 }),
    leavesDark: new THREE.MeshStandardMaterial({ color: 0x0f613c, roughness: 0.7 }),
    rock: new THREE.MeshStandardMaterial({ color: 0x7b7f8e, roughness: 0.95 }),
    wood: new THREE.MeshStandardMaterial({ map: woodTexture, roughness: 0.78 }),
    crystal: new THREE.MeshStandardMaterial({
      map: crystalTexture,
      color: 0x62f7ff,
      emissive: 0x116b84,
      emissiveIntensity: 0.65,
      roughness: 0.25,
      metalness: 0.05,
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
    beacon: new THREE.MeshStandardMaterial({
      color: 0xd7ecff,
      metalness: 0.2,
      roughness: 0.35,
    }),
    beaconDark: new THREE.MeshStandardMaterial({
      color: 0x29334f,
      metalness: 0.45,
      roughness: 0.3,
    }),
    beam: new THREE.MeshBasicMaterial({
      color: 0x53e5ff,
      transparent: true,
      opacity: 0.22,
      side: THREE.DoubleSide,
      depthWrite: false,
    }),
    tent: new THREE.MeshStandardMaterial({ color: 0xfff1c0, roughness: 0.72, side: THREE.DoubleSide }),
    tentTrim: new THREE.MeshStandardMaterial({ color: 0xf0b35d, roughness: 0.76 }),
    tentDoor: new THREE.MeshStandardMaterial({ color: 0x1c1b1a, roughness: 0.9, side: THREE.DoubleSide }),
    rope: new THREE.MeshStandardMaterial({ color: 0xd3c18f, roughness: 0.82 }),
    gold: new THREE.MeshStandardMaterial({
      color: 0xffd45a,
      emissive: 0x6f4700,
      emissiveIntensity: 0.35,
      metalness: 0.65,
      roughness: 0.25,
    }),
  };
}

function addLights() {
  // Night mode uses the beacon/low-angle light as the main shadow source.
  // Inactive beacon = soft/light shadows. Active beacon = stronger light + darker shadows.

  ambientLightRef = new THREE.AmbientLight(0x8ca7c8, 0.32);
  scene.add(ambientLightRef);

  hemisphereLightRef = new THREE.HemisphereLight(0x9ed7ff, 0x26401e, 0.68);
  scene.add(hemisphereLightRef);

  directionalLightRef = new THREE.DirectionalLight(0xddeaff, 0.14);
  // Slightly angled instead of perfectly top-down, so shadows are visible on the ground.
  directionalLightRef.position.set(4.5, 9.5, 6.0);
  directionalLightRef.castShadow = true;
  directionalLightRef.shadow.mapSize.set(2048, 2048);
  directionalLightRef.shadow.camera.left = -20;
  directionalLightRef.shadow.camera.right = 20;
  directionalLightRef.shadow.camera.top = 20;
  directionalLightRef.shadow.camera.bottom = -20;
  directionalLightRef.shadow.camera.near = 0.5;
  directionalLightRef.shadow.camera.far = 45;
  directionalLightRef.shadow.bias = -0.00035;
  directionalLightRef.shadow.normalBias = 0.02;
  directionalLightRef.shadow.radius = 4;
  directionalLightRef.target.position.set(0, 0, 0);
  scene.add(directionalLightRef);
  scene.add(directionalLightRef.target);

  beaconLight = new THREE.PointLight(0x54e6ff, 2.3, 18, 2);
  beaconLight.position.set(0, 4.7, 0);
  // Let the actual beacon point light cast radial shadows at night.
  beaconLight.castShadow = true;
  beaconLight.shadow.mapSize.set(2048, 2048);
  beaconLight.shadow.camera.near = 0.15;
  beaconLight.shadow.camera.far = 38;
  beaconLight.shadow.bias = -0.00018;
  beaconLight.shadow.normalBias = 0.025;
  beaconLight.shadow.radius = 3;
  scene.add(beaconLight);

  // This spotlight sits at the beacon and adds the visible cone/brightness.
  spotLightRef = new THREE.SpotLight(0x99e8ff, 1.2, 24, Math.PI / 3.0, 0.6, 1.1);
  spotLightRef.position.set(0, 4.9, 0);
  spotLightRef.target.position.set(0, 0, 0);
  spotLightRef.castShadow = true;
  spotLightRef.shadow.mapSize.set(3072, 3072);
  spotLightRef.shadow.camera.near = 0.5;
  spotLightRef.shadow.camera.far = 24;
  spotLightRef.shadow.bias = -0.00012;
  spotLightRef.shadow.normalBias = 0.014;
  spotLightRef.shadow.radius = 5;
  scene.add(spotLightRef);
  scene.add(spotLightRef.target);

  // Focused shadow light for the floating satellite/drone.
  satelliteShadowLight = new THREE.DirectionalLight(0xffefb8, 0.0);
  satelliteShadowLight.position.set(7.6, 8.8, 5.6);
  satelliteShadowLight.castShadow = true;
  satelliteShadowLight.shadow.mapSize.set(2048, 2048);
  satelliteShadowLight.shadow.camera.left = -4.5;
  satelliteShadowLight.shadow.camera.right = 4.5;
  satelliteShadowLight.shadow.camera.top = 4.5;
  satelliteShadowLight.shadow.camera.bottom = -4.5;
  satelliteShadowLight.shadow.camera.near = 0.5;
  satelliteShadowLight.shadow.camera.far = 18;
  satelliteShadowLight.shadow.bias = -0.00018;
  satelliteShadowLight.shadow.normalBias = 0.016;
  satelliteShadowLight.shadow.radius = 1.6;
  satelliteShadowLight.target.position.set(3.3, 3.8, 2.8);
  scene.add(satelliteShadowLight);
  scene.add(satelliteShadowLight.target);
}

function addIsland(materials) {
  // Primary shapes: cylinder island, cylinder water, torus shore ring.
  const island = new THREE.Mesh(
    new THREE.CylinderGeometry(8.5, 9.2, 0.9, 96),
    materials.ground
  );
  island.position.y = -0.45;
  // Do not let the cylinder side receive shadows. When the camera looks outward,
  // shadows on the vertical island wall show up as large black triangles/wedges.
  island.receiveShadow = false;
  scene.add(island);

  // Separate flat top layer: it receives normal ground shadows, but it has no
  // vertical side faces, so the outside-edge triangle artifact cannot appear.
  const islandTop = new THREE.Mesh(
    new THREE.CircleGeometry(8.52, 128),
    materials.ground
  );
  islandTop.rotation.x = -Math.PI / 2;
  islandTop.position.y = 0.012;
  islandTop.receiveShadow = true;
  scene.add(islandTop);

  const water = new THREE.Mesh(
    new THREE.CylinderGeometry(18, 18, 0.08, 128),
    materials.water
  );
  water.position.y = -0.74;
  // The semi-transparent ocean should not receive shadows.
  // Otherwise small objects near the shoreline can project large dark wedges
  // when viewed toward the outside of the island.
  water.receiveShadow = false;
  scene.add(water);
  animatedObjects.push({ object: water, type: 'water' });

  const shoreRing = new THREE.Mesh(
    new THREE.TorusGeometry(8.7, 0.12, 12, 120),
    new THREE.MeshStandardMaterial({ color: 0xc7b574, roughness: 0.9 })
  );
  shoreRing.rotation.x = Math.PI / 2;
  shoreRing.position.y = 0.03;
  // The ring is bright trim; shadows on it can create harsh black spikes at the edge.
  shoreRing.receiveShadow = false;
  scene.add(shoreRing);
}


function addOceanEffects() {
  // Extra visual polish: animated foam rings and a moon/reflection over the ocean.
  const foamMaterial = new THREE.MeshBasicMaterial({
    color: 0xb9f7ff,
    transparent: true,
    opacity: 0.16,
    depthWrite: false,
  });

  for (let i = 0; i < 6; i++) {
    const wave = new THREE.Mesh(
      new THREE.TorusGeometry(9.4 + i * 1.25, 0.028, 8, 160),
      foamMaterial.clone()
    );
    wave.rotation.x = Math.PI / 2;
    wave.position.y = -0.66 + i * 0.002;
    wave.userData.baseScale = 1 + i * 0.01;
    wave.userData.phase = i * 0.75;
    scene.add(wave);
    waveRings.push(wave);
  }

  moon = new THREE.Group();
  const moonDisk = new THREE.Mesh(
    new THREE.SphereGeometry(0.75, 32, 16),
    new THREE.MeshBasicMaterial({ color: 0xfff0bf })
  );
  moon.add(moonDisk);

  const moonGlow = new THREE.PointLight(0xddeeff, 0.75, 28, 2);
  moonGlow.position.set(0, 0, 0);
  moon.add(moonGlow);

  moon.position.set(-10, 10, -13);
  scene.add(moon);

  for (let i = 0; i < 5; i++) {
    const reflection = new THREE.Mesh(
      new THREE.PlaneGeometry(1.2 - i * 0.13, 0.045),
      new THREE.MeshBasicMaterial({
        color: 0xe4f8ff,
        transparent: true,
        opacity: 0.16 - i * 0.018,
        side: THREE.DoubleSide,
        depthWrite: false,
      })
    );
    reflection.rotation.x = -Math.PI / 2;
    reflection.position.set(-4.5, -0.61, -7.5 + i * 0.38);
    reflection.userData.phase = i * 0.5;
    scene.add(reflection);
    waveRings.push(reflection);
  }
}

function createTextBoardTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#3a2515';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#6d4425';
  for (let y = 28; y < canvas.height; y += 52) {
    ctx.fillRect(0, y, canvas.width, 7);
  }

  ctx.strokeStyle = '#d9b16f';
  ctx.lineWidth = 10;
  ctx.strokeRect(18, 18, canvas.width - 36, canvas.height - 36);

  ctx.textAlign = 'center';
  ctx.fillStyle = '#fff0bd';
  ctx.font = 'bold 40px Arial';
  ctx.fillText('PORTAL QUEST', canvas.width / 2, 76);
  ctx.font = 'bold 30px Arial';
  ctx.fillText('Click all 5 crystals', canvas.width / 2, 134);
  ctx.fillText('to activate the portal', canvas.width / 2, 178);
  ctx.font = '22px Arial';
  ctx.fillText('Interactive Three.js Scene', canvas.width / 2, 222);

  const texture = new THREE.CanvasTexture(canvas);
  texture.encoding = THREE.sRGBEncoding;
  return texture;
}

function addGuideSign(materials) {
  // In-world instruction sign using a canvas texture.
  const signGroup = new THREE.Group();
  signGroup.position.set(-4.1, 0.0, -1.2);
  signGroup.rotation.y = 0.5;

  const signPostHeight = 0.54;
  const leftPost = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.055, signPostHeight, 8), materials.trunk);
  leftPost.position.set(-0.55, signPostHeight / 2, 0);
  leftPost.castShadow = true;
  leftPost.receiveShadow = true;
  const rightPost = leftPost.clone();
  rightPost.position.x = 0.55;
  rightPost.castShadow = true;
  rightPost.receiveShadow = true;
  signGroup.add(leftPost);
  signGroup.add(rightPost);

  const signTexture = createTextBoardTexture();
  const board = new THREE.Mesh(
    new THREE.BoxGeometry(1.55, 0.78, 0.07),
    new THREE.MeshStandardMaterial({ map: signTexture, roughness: 0.74 })
  );
  board.position.set(0, 0.92, 0.02);
  board.castShadow = true;
  board.receiveShadow = true;
  signGroup.add(board);

  scene.add(signGroup);
}

function addTreasureChest(materials) {
  // Reward chest using the previous compact chest design, but with the working
  // back-hinge/open behavior from the fixed version.
  const chestGroup = new THREE.Group();
  chestGroup.name = 'Treasure chest - previous design, working open animation';
  chestGroup.position.set(-1.2, 0.0, 3.9);
  chestGroup.rotation.y = 0.45;
  chestGroup.scale.setScalar(0.68);

  const chestBase = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.44, 0.62), materials.wood);
  chestBase.position.y = 0.22;
  chestBase.castShadow = true;
  chestBase.receiveShadow = true;
  chestGroup.add(chestBase);

  // Small dark interior so the chest looks hollow after opening.
  const inside = new THREE.Mesh(
    new THREE.BoxGeometry(0.82, 0.04, 0.46),
    new THREE.MeshStandardMaterial({ color: 0x23170c, roughness: 0.95 })
  );
  inside.position.set(0, 0.455, 0);
  chestGroup.add(inside);

  // Back-edge hinge. The mesh is offset forward from this pivot, so negative X
  // rotation raises the front/latch side visibly while keeping the old design.
  chestLidPivot = new THREE.Group();
  chestLidPivot.position.set(0, 0.55, -0.34);
  chestLidPivot.userData.targetRotationX = 0;
  chestLidPivot.userData.isOpen = false;
  chestGroup.add(chestLidPivot);

  chestLid = new THREE.Mesh(new THREE.BoxGeometry(1.02, 0.2, 0.68), materials.wood);
  chestLid.position.set(0, 0, 0.33);
  chestLid.castShadow = true;
  chestLid.receiveShadow = true;
  chestLidPivot.add(chestLid);

  const latch = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.16, 0.05), materials.gold);
  latch.position.set(0, -0.05, 0.67);
  latch.castShadow = true;
  chestLidPivot.add(latch);

  chestCoins = [];
  for (let i = 0; i < 8; i++) {
    const coin = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.025, 18), materials.gold);
    coin.rotation.x = Math.PI / 2;
    coin.position.set(-0.3 + (i % 4) * 0.2, 0.5 + Math.floor(i / 4) * 0.04, 0.02 + (i % 2) * 0.13);
    coin.userData.baseY = coin.position.y;
    coin.visible = false;
    coin.castShadow = true;
    chestGroup.add(coin);
    chestCoins.push(coin);
  }

  chestGlow = new THREE.PointLight(0xffd15a, 0, 4, 2);
  chestGlow.position.set(0, 0.72, 0);
  chestGroup.add(chestGlow);

  scene.add(chestGroup);
}

function addTrees(materials) {
  const treePositions = [
    [-6.4, 0, -2.3],
    [-5.1, 0, 3.9],
    [-2.7, 0, -5.8],
    [3.5, 0, -5.1],
    [7, 0, -1.4],
    [5.1, 0, 4.2],
    [-1.1, 0, 5.9],
  ];

  treePositions.forEach((position, index) => {
    const trunk = new THREE.Mesh(
      new THREE.CylinderGeometry(0.18, 0.25, 1.6, 16),
      materials.trunk
    );
    trunk.position.set(position[0], 0.8, position[2]);
    trunk.castShadow = true;
    trunk.receiveShadow = true;
    scene.add(trunk);

    const leafShape = index % 2 === 0
      ? new THREE.ConeGeometry(0.9, 1.8, 24)
      : new THREE.SphereGeometry(0.82, 24, 16);
    const leaves = new THREE.Mesh(leafShape, index % 2 === 0 ? materials.leaves : materials.leavesDark);
    leaves.position.set(position[0], 1.85, position[2]);
    leaves.castShadow = true;
    leaves.receiveShadow = true;
    scene.add(leaves);
  });
}

function addRocks(materials) {
  const rockPositions = [
    [-7.0, 0.08, 1.3],
    [-4.4, 0.07, -4.4],
    [-5.25, 0.09, 4.85],
    [1.7, 0.09, -6.5],
    [3.6, 0.08, 5.7],
    [6.6, 0.08, 1.1],
    [0.5, 0.06, 6.8],
    [6.9, 0.06, -3.4],
  ];

  rockPositions.forEach((position, index) => {
    const rock = new THREE.Mesh(
      new THREE.DodecahedronGeometry(0.35 + (index % 3) * 0.1, 0),
      materials.rock
    );
    rock.position.set(position[0], position[1], position[2]);
    rock.rotation.set(index * 0.3, index * 0.7, index * 0.2);
    rock.scale.set(1.2, 0.65 + (index % 2) * 0.25, 0.9);
    rock.castShadow = true;
    rock.receiveShadow = true;
    scene.add(rock);
  });
}

function createTentBodyGeometry(width, height, length) {
  // A-frame triangular prism tent body.
  const halfWidth = width / 2;
  const halfLength = length / 2;
  const vertices = new Float32Array([
    -halfWidth, 0, halfLength,   halfWidth, 0, halfLength,    0, height, halfLength,
    -halfWidth, 0, -halfLength,  halfWidth, 0, -halfLength,   0, height, -halfLength,
  ]);

  const indices = [
    0, 1, 2,      // front triangle
    3, 5, 4,      // back triangle
    0, 2, 5,  0, 5, 3,  // left roof panel
    1, 4, 5,  1, 5, 2,  // right roof panel
    0, 3, 4,  0, 4, 1,  // bottom panel
  ];

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function createTriangleGeometry(a, b, c) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    a.x, a.y, a.z,
    b.x, b.y, b.z,
    c.x, c.y, c.z,
  ]), 3));
  geometry.setIndex([0, 1, 2]);
  geometry.computeVertexNormals();
  return geometry;
}

function createCylinderBetween(start, end, radius, material, radialSegments = 8) {
  const direction = new THREE.Vector3().subVectors(end, start);
  const length = direction.length();
  const cylinder = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, length, radialSegments),
    material
  );
  cylinder.position.copy(start).add(end).multiplyScalar(0.5);
  cylinder.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  cylinder.castShadow = true;
  cylinder.receiveShadow = true;
  return cylinder;
}

function addCampsite(materials) {
  // A small campsite adds textured boxes, cylinders, cones, and a clearer A-frame tent.
  const tentGroup = new THREE.Group();
  tentGroup.position.set(-2.2, 0, 2.5);
  tentGroup.rotation.y = -0.25;

  // No platform under the tent; the A-frame canvas sits directly on the island.

  const tentBody = new THREE.Mesh(
    createTentBodyGeometry(1.85, 1.28, 2.25),
    materials.tent
  );
  tentBody.position.y = 0.0;
  tentBody.castShadow = true;
  tentBody.receiveShadow = true;
  tentGroup.add(tentBody);

  const door = new THREE.Mesh(
    createTriangleGeometry(
      new THREE.Vector3(-0.36, 0.02, 1.15),
      new THREE.Vector3(0.36, 0.02, 1.15),
      new THREE.Vector3(0, 0.86, 1.15)
    ),
    materials.tentDoor
  );
  door.position.y = 0.0;
  door.castShadow = true;
  tentGroup.add(door);

  const flapLeft = new THREE.Mesh(
    createTriangleGeometry(
      new THREE.Vector3(-0.36, 0.02, 1.17),
      new THREE.Vector3(0, 0.86, 1.17),
      new THREE.Vector3(-0.78, 0.02, 1.17)
    ),
    materials.tentTrim
  );
  flapLeft.position.y = 0.0;
  flapLeft.rotation.y = -0.18;
  flapLeft.castShadow = true;
  tentGroup.add(flapLeft);

  const flapRight = flapLeft.clone();
  flapRight.geometry = createTriangleGeometry(
    new THREE.Vector3(0.36, 0.02, 1.17),
    new THREE.Vector3(0.78, 0.02, 1.17),
    new THREE.Vector3(0, 0.86, 1.17)
  );
  flapRight.rotation.y = 0.18;
  tentGroup.add(flapRight);

  const ridgeStart = new THREE.Vector3(0, 1.31, -1.22);
  const ridgeEnd = new THREE.Vector3(0, 1.31, 1.22);
  tentGroup.add(createCylinderBetween(ridgeStart, ridgeEnd, 0.035, materials.rope, 10));
  tentGroup.add(createCylinderBetween(new THREE.Vector3(0, 0.02, 1.18), new THREE.Vector3(0, 1.26, 1.18), 0.035, materials.rope, 10));
  tentGroup.add(createCylinderBetween(new THREE.Vector3(0, 0.02, -1.18), new THREE.Vector3(0, 1.26, -1.18), 0.035, materials.rope, 10));

  const ropePoints = [
    [new THREE.Vector3(0, 1.26, 1.18), new THREE.Vector3(-1.12, 0.04, 1.55)],
    [new THREE.Vector3(0, 1.26, 1.18), new THREE.Vector3(1.12, 0.04, 1.55)],
    [new THREE.Vector3(0, 1.26, -1.18), new THREE.Vector3(-1.12, 0.04, -1.55)],
    [new THREE.Vector3(0, 1.26, -1.18), new THREE.Vector3(1.12, 0.04, -1.55)],
  ];
  ropePoints.forEach(([start, end]) => {
    tentGroup.add(createCylinderBetween(start, end, 0.015, materials.rope, 6));
  });

  scene.add(tentGroup);

  const campfireBase = new THREE.Mesh(
    new THREE.CylinderGeometry(0.55, 0.65, 0.18, 24),
    new THREE.MeshStandardMaterial({ color: 0x2b2b2b, roughness: 0.8 })
  );
  campfireBase.position.set(-0.4, 0.09, 2.9);
  campfireBase.castShadow = true;
  campfireBase.receiveShadow = true;
  scene.add(campfireBase);

  const flame = new THREE.Mesh(
    new THREE.ConeGeometry(0.35, 0.95, 24),
    new THREE.MeshBasicMaterial({ color: 0xff9b31, transparent: true, opacity: 0.82 })
  );
  flame.position.set(-0.4, 0.72, 2.9);
  scene.add(flame);
  animatedObjects.push({ object: flame, type: 'flame' });

  const fireLight = new THREE.PointLight(0xff8d2a, 1.7, 8, 2);
  fireLight.position.set(-0.4, 1.1, 2.9);
  scene.add(fireLight);
  animatedObjects.push({ object: fireLight, type: 'fireLight' });

  const cratePositions = [
    [-3.95, 0.35, 2.9],
    [-3.65, 0.35, 3.75],
    [-4.45, 0.35, 3.65],
  ];

  cratePositions.forEach((position, index) => {
    const crate = new THREE.Mesh(
      new THREE.BoxGeometry(0.7, 0.7, 0.7),
      materials.wood
    );
    crate.position.set(position[0], position[1], position[2]);
    crate.rotation.y = index * 0.4;
    crate.castShadow = true;
    crate.receiveShadow = true;
    scene.add(crate);
  });
}

function addCrystals(materials) {
  const crystalPositions = [
    [-5.6, 0.125, -0.4],
    [-2.4, 0.125, -4.3],
    [2.4, 0.125, -4.8],
    [5.2, 0.125, 2.3],
    [0.6, 0.125, 5.2],
  ];

  crystalPositions.forEach((position, index) => {
    const group = new THREE.Group();
    group.position.set(position[0], position[1], position[2]);

    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(0.34, 0.42, 0.25, 6),
      new THREE.MeshStandardMaterial({ color: 0x1d3155, roughness: 0.45 })
    );
    // Disable crystal-base shadows too, so no dark wedge appears behind edge crystals.
    base.castShadow = false;
    base.receiveShadow = false;
    group.add(base);

    const crystal = new THREE.Mesh(
      new THREE.ConeGeometry(0.42, 1.25, 6),
      materials.crystal
    );
    crystal.position.y = 0.72;
    // Transparent crystal shadows were creating a large black triangle artifact
    // on the background. Let the base/platform cast the shadow instead.
    crystal.castShadow = false;
    crystal.receiveShadow = false;
    crystal.userData.collectable = true;
    crystal.userData.group = group;
    crystal.userData.index = index;
    group.add(crystal);

    const glow = new THREE.PointLight(0x5bf3ff, 1.25, 5, 2);
    glow.position.y = 0.9;
    group.add(glow);

    group.userData.collected = false;
    group.userData.baseY = position[1];
    group.userData.glow = glow;
    group.userData.crystalMesh = crystal;
    group.userData.baseMesh = base;
    group.userData.index = index;

    scene.add(group);
    crystalTargets.push(crystal);
    activeCrystalTargets.push(crystal);
    crystals.push(group);
  });
}

